-- Table structure for table `suppliers`
--

CREATE TABLE `suppliers` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `local_id` bigint(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `mobile` varchar(255) NOT NULL,
  `email` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `state` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `zip_code` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `due_amount` double DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `company_id` bigint(20) DEFAULT 1,
  `type` int(11) NOT NULL DEFAULT 0,
  `credit` double NOT NULL DEFAULT 0,
  `active` int(11) NOT NULL DEFAULT 1,
  `limit` double NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `supply_item_batches`
--

CREATE TABLE `supply_item_batches` (
  `id` bigint(20) NOT NULL,
  `material_id` bigint(20) NOT NULL,
  `supply_order_item_id` bigint(20) NOT NULL COMMENT 'FK إلى supply_order_items.id',
  `material_batch_id` bigint(20) NOT NULL COMMENT 'الدفعة المستخدمة من material_batches',
  `unit_id` bigint(20) NOT NULL COMMENT 'وحدة القياس المستخدمة في هذا السحب',
  `quantity` decimal(15,3) NOT NULL COMMENT 'كمية الخام المسحوبة من الدفعة',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `supply_orders`
--

CREATE TABLE `supply_orders` (
  `id` int(11) NOT NULL,
  `factory_id` int(11) NOT NULL COMMENT 'رقم المصنع أو الوحدة الإنتاجية',
  `admin_id` int(11) NOT NULL COMMENT 'منشئ الأمر',
  `order_date` date NOT NULL COMMENT 'تاريخ أمر التوريد',
  `status` enum('draft','issued','completed','ended') NOT NULL DEFAULT 'draft',
  `note` text DEFAULT NULL COMMENT 'ملاحظات عامة',
  `expected_cost` decimal(15,2) DEFAULT NULL COMMENT 'التكلفة المتوقعة الإجمالية',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `supply_order_items`
--

CREATE TABLE `supply_order_items` (
  `id` bigint(20) NOT NULL,
  `supply_order_id` bigint(20) NOT NULL COMMENT 'FK إلى supply_orders.id',
  `product_id` bigint(20) NOT NULL COMMENT 'المنتَج المراد انتاجه',
  `product_quantity` decimal(15,3) NOT NULL COMMENT 'كمية المنتج المراد انتاجه',
  `expected_cost_per_unit` decimal(15,2) NOT NULL COMMENT 'التكلفة المتوقعة لإنتاج وحدة واحدة',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

